-- 0.16.0, T254 (D189): an audit page of a place, of a reader's places, or of refusals costs the same however long the log grows (R48), so that 0.16's 5 s `statement_timeout` on the app's login holds for it. Additive (AGENTS.md, "expand, then contract"): indexes alone, which the previous release's code never reads.
--
-- Every one is built without blocking writes, after the migrations' transaction commits (`online-indexes.ts`).
-- A place's are keyed by an expression no older index is keyed by (`placeKey`, `besideKey`), which its reads ask by: its uuid's 16 bytes by its column, the text of `also` (which nothing holds to name uuids, and a cast in an index would fail its insert on one that does not). Asked by the column, Postgres read the older index by the same place, `audit_log_environment_idx`, which holds every entry about it, walked back or whole, past every detail entry about the place (1,059 pages past 20,000 of an environment's `mcp.read`, 5 through its own index).
-- The refusals an ordinary page shows (`entriesOf('denied')`, `?decision=deny`), keyed by decision, which its reads leave unfixed (`KINDS.denied`): a page of them back from the newest walked every entry allowed since (35 pages 4,000 allowed entries in, 334 at 40,000).
CREATE INDEX CONCURRENTLY "audit_log_denied_idx" ON "audit_log" USING btree ("decision","seq") WHERE decision <> 'allow' AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
-- The shown entries about a place, by its column (`shownAt`): a page back from the newest walked every shown entry about another place through `audit_log_shown_idx`, or every one it hides about its own through `audit_log_project_idx` (157 pages to 1,555 for a project's page 4,000 and 40,000 entries in, 304 to 3,023 for an environment's or a key's). A reader of some places reads each of theirs so (148 pages to 1,471 before).
CREATE INDEX CONCURRENTLY "audit_log_project_shown_idx" ON "audit_log" USING btree ((uuid_send("project_id")),"seq") WHERE project_id IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
CREATE INDEX CONCURRENTLY "audit_log_environment_shown_idx" ON "audit_log" USING btree ((uuid_send("environment_id")),"seq") WHERE environment_id IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
CREATE INDEX CONCURRENTLY "audit_log_secret_shown_idx" ON "audit_log" USING btree ((uuid_send("secret_id")),"seq") WHERE secret_id IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
-- And those that name the place besides their own (`also`), a reference's other side, past none of the `reference.create` seals the page hides.
CREATE INDEX CONCURRENTLY "audit_log_also_project_shown_idx" ON "audit_log" USING btree ((("metadata")::jsonb #>> '{also,projectId}'),"seq") WHERE (("audit_log"."metadata")::jsonb -> 'also') IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
CREATE INDEX CONCURRENTLY "audit_log_also_environment_shown_idx" ON "audit_log" USING btree ((("metadata")::jsonb #>> '{also,environmentId}'),"seq") WHERE (("audit_log"."metadata")::jsonb -> 'also') IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
CREATE INDEX CONCURRENTLY "audit_log_also_secret_shown_idx" ON "audit_log" USING btree ((("metadata")::jsonb #>> '{also,secretId}'),"seq") WHERE (("audit_log"."metadata")::jsonb -> 'also') IS NOT NULL AND action NOT IN ('sign_in', 'sign_out', 'token.create', 'token.revoke', 'device.approve', 'device.deny', 'mcp.token', 'mcp.read', 'account.link', 'account.unlink', 'passkey.check', 'key.wrap', 'key.rewrap', 'reference.create', 'key.intent', 'key.check', 'audit.heartbeat', 'audit.checkpoint', 'key.reseal') AND seq >= 0;--> statement-breakpoint
-- A key's environment's reads of several keys in 0.14's log (`LISTED_READS`), whose keys only the metadata lists: a key's page reads these, and none of its environment's other entries. This release writes none once its vault serves 0.15's uses (docs/history-sweep.md).
CREATE INDEX CONCURRENTLY "audit_log_listed_idx" ON "audit_log" USING btree ((uuid_send("environment_id")),"seq") WHERE action = 'secret.read' AND secret_id IS NULL;